<?php require __DIR__.'/includes/functions.php';require __DIR__.'/includes/data.php';$q=trim($_GET['q']??'');$results=[];if($q!==''){$needle=mb_strtolower($q);foreach(packages() as $p){$hay=mb_strtolower($p['title'].' '.$p['summary'].' '.$p['category'].' '.$p['location']);if(str_contains($hay,$needle))$results[]=['type'=>'Trip','title'=>$p['title'],'text'=>$p['summary'],'url'=>'/package/'.$p['slug']];}foreach(destinations() as $d){$hay=mb_strtolower($d['name'].' '.$d['text']);if(str_contains($hay,$needle))$results[]=['type'=>'Destination','title'=>$d['name'],'text'=>$d['text'],'url'=>'/destinations#'.$d['slug']];}}$pageMeta=meta('Search','Search Tanzania Wildlife Epic trips and destinations.');require __DIR__.'/includes/header.php';?>
<main><section class="inner-hero"><div class="wrap"><h1>Search Tanzania Wildlife Epic</h1><form class="contact-form" method="get" action="/search"><input name="q" value="<?=e($q)?>" placeholder="Search safari, Kilimanjaro, Zanzibar, destinations..." autofocus><button class="btn gold">Search</button></form></div></section><section class="section wrap"><h2><?= $q!=='' ? 'Results for “'.e($q).'”' : 'Find a trip or destination' ?></h2><?php if($q!==''&&!$results):?><p>No matching results yet. Try a broader term or <a href="/contact"><strong>ask us directly</strong></a>.</p><?php endif;?><div class="cards"><?php foreach($results as $r):?><article class="trip-card"><div class="trip-body"><span><?=e($r['type'])?></span><h3><?=e($r['title'])?></h3><p><?=e($r['text'])?></p><a href="<?=e($r['url'])?>">Open →</a></div></article><?php endforeach;?></div></section></main><?php require __DIR__.'/includes/footer.php';?>
